// Ranges do solver da aula de ICM: o mesmo spot com 25% e com 16% do field left.
// Fonte: theory/13-ICM/03-Solver-Ranges.html. Cada mão tem 3 dígitos (raise, all-in, call) de 0 a 9.

export interface SolverMedia {
  raise: number
  fold: number
  allin: number
  call: number
}
export interface FotoMesa {
  avg: number
  pct: number
  seats: [string, number, string[], number, boolean][]
}
export interface SpotIcm {
  title: string
  g25: string
  g16: string
  m25: SolverMedia
  m16: SolverMedia
  ctx: string
  // nomes das ações: raise, shove, call, fold
  lab: [string, string, string, string]
  open: boolean
  st25: FotoMesa
  st16: FotoMesa
}

